package repository.impl;import entity.Rang;import i_repository.Rang_IDAO;import java.util.List;import mapper.RangMapper;public class Rang_DAO extends AbstractDAO<Rang> implements Rang_IDAO {    @Override    public List<Rang> findAllRang() {        String sql = "SELECT * FROM Rang";        return findAll(sql, new RangMapper());    }    @Override    public Rang findById(String maRang) {        String sql = "SELECT * FROM Rang WHERE maRang = ?";        List<Rang> ds = findAll(sql, new RangMapper(), maRang);        if (ds == null || ds.isEmpty()) {            return null;        }        return ds.get(0);    }    @Override    public Integer add(Rang entity) {        String sql = "INSERT INTO Rang(maRang,tenRang,maLoaiRang) VALUES(?,?,?)";        return add(sql, entity.getMaRang(), entity.getTenRang(), entity.getMaLoaiRang());    }    @Override    public void update(Rang entity) {        String sql = "UPDATE Rang SET tenRang = ?, maLoaiRang = ? WHERE maRang = ?";        update(sql, entity.getTenRang(), entity.getMaLoaiRang(), entity.getMaRang());    }    @Override    public void delete(String maRang) {        String sql = "DELETE FROM Rang WHERE maRang = ?";        delete(sql, maRang);    }}